1	'use strict';
2	
3	(function () {
4	  const NO_REPLY = 'Could not reach the server.';
5	  const REQUEST_FAILED = 'Request failed.';
6	
7	  const form = document.getElementById('booking-form');
8	  const roomSelect = document.getElementById('room');
9	  const titleInput = document.getElementById('title');
10	  const dateInput = document.getElementById('date');
11	  const startInput = document.getElementById('start');
12	  const endInput = document.getElementById('end');
13	  const bookButton = document.getElementById('book');
14	  const filterInput = document.getElementById('filter-date');
15	  const showAllButton = document.getElementById('show-all');
16	  const list = document.getElementById('booking-list');
17	  const errorBox = document.getElementById('error');
18	
19	  let listSeq = 0;
20	
21	  function showError(message) {
22	    errorBox.textContent = message;
23	  }
24	
25	  function isObject(value) {
26	    return typeof value === 'object' && value !== null && !Array.isArray(value);
27	  }
28	
29	  function errorMessage(body) {
30	    return isObject(body) && typeof body.error === 'string' ? body.error : REQUEST_FAILED;
31	  }
32	
33	  // Resolves to null when there is no usable reply (network failure, or a
34	  // non-204 body that is not JSON); otherwise to { status, body }.
35	  async function request(method, url, payload) {
36	    const options = { method };
37	    if (payload !== undefined) {
38	      options.headers = { 'Content-Type': 'application/json' };
39	      options.body = JSON.stringify(payload);
40	    }
41	    try {
42	      const res = await fetch(url, options);
43	      if (res.status === 204) {
44	        return { status: 204, body: undefined };
45	      }
46	      const body = await res.json();
47	      return { status: res.status, body };
48	    } catch {
49	      return null;
50	    }
51	  }
52	
53	  function renderRooms(rooms) {
54	    const options = rooms.map((name) => {
55	      const option = document.createElement('option');
56	      option.value = name;
57	      option.textContent = name;
58	      return option;
59	    });
60	    roomSelect.replaceChildren(...options);
61	  }
62	
63	  async function loadRooms() {
64	    const reply = await request('GET', '/api/rooms');
65	    if (reply === null) {
66	      showError(NO_REPLY);
67	      return;
68	    }
69	    if (reply.status !== 200) {
70	      showError(errorMessage(reply.body));
71	      return;
72	    }
73	    const rooms = isObject(reply.body) ? reply.body.rooms : undefined;
74	    if (!Array.isArray(rooms)) {
75	      showError(REQUEST_FAILED);
76	      return;
77	    }
78	    renderRooms(rooms);
79	  }
80	
81	  function bookingItem(booking) {
82	    const li = document.createElement('li');
83	    const cancel = document.createElement('button');
84	    cancel.type = 'button';
85	    cancel.textContent = 'Cancel';
86	    cancel.addEventListener('click', () => cancelBooking(booking.id, cancel));
87	    li.append(
88	      `${booking.date} ${booking.start}-${booking.end} ${booking.room}: ${booking.title}`,
89	      cancel
90	    );
91	    return li;
92	  }
93	
94	  function renderBookings(bookings) {
95	    if (bookings.length === 0) {
96	      const empty = document.createElement('li');
97	      empty.append('No bookings.');
98	      list.replaceChildren(empty);
99	      return;
100	    }
101	    list.replaceChildren(...bookings.map(bookingItem));
102	  }
103	
104	  function listUrl() {
105	    const date = filterInput.value;
106	    return date === '' ? '/api/bookings' : `/api/bookings?date=${date}`;
107	  }
108	
109	  async function loadList() {
110	    listSeq += 1;
111	    const mine = listSeq;
112	    const reply = await request('GET', listUrl());
113	    if (mine !== listSeq) {
114	      return;
115	    }
116	    if (reply === null) {
117	      showError(NO_REPLY);
118	      return;
119	    }
120	    if (reply.status !== 200) {
121	      showError(errorMessage(reply.body));
122	      return;
123	    }
124	    const bookings = isObject(reply.body) ? reply.body.bookings : undefined;
125	    if (!Array.isArray(bookings)) {
126	      showError(REQUEST_FAILED);
127	      return;
128	    }
129	    renderBookings(bookings);
130	  }
131	
132	  async function submitBooking(event) {
133	    event.preventDefault();
134	    if (bookButton.disabled) {
135	      return;
136	    }
137	    bookButton.disabled = true;
138	    const reply = await request('POST', '/api/bookings', {
139	      room: roomSelect.value,
140	      title: titleInput.value,
141	      date: dateInput.value,
142	      start: startInput.value,
143	      end: endInput.value,
144	    });
145	    bookButton.disabled = false;
146	    if (reply === null) {
147	      showError(NO_REPLY);
148	      return;
149	    }
150	    if (reply.status !== 201) {
151	      showError(errorMessage(reply.body));
152	      return;
153	    }
154	    titleInput.value = '';
155	    showError('');
156	    loadList();
157	  }
158	
159	  async function cancelBooking(id, button) {
160	    button.disabled = true;
161	    const reply = await request('DELETE', `/api/bookings/${id}`);
162	    button.disabled = false;
163	    if (reply === null) {
164	      showError(NO_REPLY);
165	      return;
166	    }
167	    showError(reply.status === 204 ? '' : errorMessage(reply.body));
168	    loadList();
169	  }
170	
171	  function showAll() {
172	    filterInput.value = '';
173	    loadList();
174	  }
175	
176	  form.addEventListener('submit', submitBooking);
177	  filterInput.addEventListener('change', loadList);
178	  showAllButton.addEventListener('click', showAll);
179	
180	  loadRooms();
181	  loadList();
182	})();
